def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change_ratio = (v2 - v1) / v1
    percent_decline = change_ratio * 100

    return {
        "value": percent_decline,
        "trace": {
            "start_value": v1,
            "end_value": v2,
            "change_ratio": change_ratio,
            "percent_decline": percent_decline,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
